-- cstring has no equality or ordering: keys, membership, GREATEST and rows.
select distinct 'a'::cstring;
select 'a'::cstring order by 1;
select 'a'::cstring in ('a'::cstring);
select 'a'::cstring in ('a');
select greatest('a'::cstring,'b'::cstring);
select least('a'::cstring,'b');
select array['a'::cstring];
select '{a,b}'::cstring[];
select pg_typeof('{a,b}'::cstring[]);
select ('{a,b}'::cstring[])[1] , pg_typeof(('{a,b}'::cstring[])[1]);
select array_length('{a,b}'::cstring[],1);
select '{a,b}'::cstring[] = '{a,b}'::cstring[];
select array['a'::cstring] || 'b'::cstring;
select count(distinct 'a'::cstring);
select 'a'::cstring union select 'b'::cstring;
select 'a'::cstring union all select 'b'::cstring;
select case when true then 'a'::cstring end;
select nullif('a'::cstring,'a'::cstring);
select coalesce('a'::cstring,'b'::cstring);
select x from (values ('a'::cstring),('b'::cstring)) v(x);
select x from (values ('a'::cstring),('b'::cstring)) v(x) group by x;
select max('a'::cstring);
select array_agg('a'::cstring);
select unnest('{a,b}'::cstring[]);
select '{a,b}'::cstring[]::text;
select '{a,b}'::cstring[]::text[];
select 'a'::cstring = any('{a}'::cstring[]);
select row('a'::cstring) = row('a'::cstring);
select 'a'::cstring is distinct from 'b'::cstring;
select 1 order by 'a'::cstring;
select count(distinct '{}'::json);
select count(distinct x) from (select '{}'::json as x) s;
select count(distinct x) from (select 'a'::cstring as x) s;
select array_agg(distinct 'a'::cstring);
select array_agg('a'::cstring order by 1);
select string_agg(x::text, ',' order by x) from (select 'a'::cstring as x) s;
select '{}'::json in ('{}');
select greatest('{}'::json, '{}'::json);
select nullif('{}'::json, '{}'::json);
select '{}'::json = any(array['{}'::json]);
select row('{}'::json) = row('{}'::json);
select x = any('{a}'::cstring[]) from (select 'a'::cstring x) s;
select 'a' = any('{a}'::cstring[]);
select row('a'::cstring, 1) < row('a'::cstring, 2);
select 'a'::cstring is not distinct from 'b';
select 'a'::refcursor = 'a';
select '{}'::json = '{}';
select 'a'::cstring < 'a';
select '{}'::json in ('{}', '{}');
select 'a'::cstring in ('a', 'b');
select 'a'::cstring in ('a'::cstring, 'b');
select 'a'::cstring = any(array['a']);
select 'a'::cstring = any(array['a'::cstring]);
select row('a'::cstring) = row('a');
select row('a'::cstring) < row('a'::cstring);
select 'a'::cstring is distinct from 'b';
select greatest('a'::cstring);
select greatest('{}'::json);
select least('a'::cstring, null);
select nullif('a'::cstring,'a');
select nullif('{}'::json,'{}');
select nullif(1, 'a'::cstring);
select nullif(1::int, 'x'::text);
-- cstring arrays, array type names and pseudo-type view columns.
CREATE FUNCTION f2(cstring[]) RETURNS int LANGUAGE sql AS 'select 1';
select f2('{a}');
CREATE FUNCTION f4() RETURNS cstring[] LANGUAGE sql AS $$select '{a}'::cstring[]$$;
select f4();
select pg_get_function_arguments('f2'::regproc), pg_get_function_result('f4'::regproc);
select pg_typeof(array['a'::cstring,'b']), array['a'::cstring,'b'];
select array['a'::cstring,'b'::text];
select array[1::cstring];
select '{a,"b c",NULL}'::cstring[];
select '{{a},{b}}'::cstring[];
select ('{a,b}'::cstring[])[2:2];
select array_dims('{a,b}'::cstring[]);
select cardinality('{a,b}'::cstring[]);
select array_to_string('{a,b}'::cstring[], ',');
select array_position('{a,b}'::cstring[], 'a'::cstring);
select array_cat('{a,b}'::cstring[],'{c}'::cstring[]);
select array_append('{a,b}'::cstring[],'c'::cstring);
select '{a}'::cstring[] < '{b}'::cstring[];
select '{a}'::cstring[] @> '{b}'::cstring[];
select '{a}'::text[]::cstring[];
select '{a}'::cstring[]::text[];
select '{a}'::cstring[]::int[];
select array['1'::cstring]::int[];
select distinct '{a}'::cstring[];
select '{a}'::cstring[] order by 1;
select '{a}'::cstring[] is null;
select format('%s', '{a}'::cstring[]);
select row('{a}'::cstring[]);
select to_json('{a}'::cstring[]);
select array_agg(x) from unnest('{a,b}'::cstring[]) x;
select pg_typeof(x) from unnest('{a,b}'::cstring[]) x;
select string_to_array('a,b',',')::cstring[];
select 'a'::cstring::cstring[];
select array_lower('{a}'::cstring[],1);
select array_remove('{a}'::cstring[],'a');
select array_fill('a'::cstring, array[2]);
select 'a'::text || '{b}'::cstring[];
select typname, typelem, typinput from pg_type where oid = 1263;
select '{a}'::_cstring;
create table tc2(a cstring[]);
create view vc as select '{a}'::cstring[] as a;
select ('{a,b}'::cstring[])[1] = 'a';
select array_length('{a}'::cstring[], 1);
select '{a}'::_text;
select '{a}'::_refcursor;
create view vc as select 'a'::cstring as a;
create view vc2 as select '{a}'::cstring[] as a;
create table tt as select 'a'::cstring as a;
create table tt2 as select '{a}'::cstring[] as a;
select * from (select '{a}'::cstring[] as a) s;
create view vv as select pg_sleep(0);
create table tv as select pg_sleep(0);
select '{1}'::_int4, '{x}'::_varchar;
create table t_ (a _int4);
select pg_typeof('{1}'::_int4);
DROP FUNCTION f2(cstring[]), f4();
DROP TABLE t_;
